-- RentAll demo journey logistics trail (checklists, accessories, notes, discrepancies).
-- ADDITIVE ONLY: creates one new table. Existing requests, journeys, payments and
-- Identity accounts are not modified. Safe to re-run.
CREATE TABLE IF NOT EXISTS rentall."PercursoDemoEventos" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PedidoId" integer NOT NULL REFERENCES rentall."PercursosAluguerDemo"("PedidoId") ON DELETE CASCADE,
  "AutorId" varchar(450) NOT NULL,
  "Papel" varchar(16) NOT NULL CHECK ("Papel" IN ('anunciante','locatario')),
  "Operacao" varchar(32) NOT NULL,
  "EstadoArtigo" varchar(32) NULL CHECK ("EstadoArtigo" IS NULL OR
    "EstadoArtigo" IN ('como_novo','bom','marcas_uso','danificado')),
  "Acessorios" varchar(300) NULL,
  "Nota" varchar(500) NULL,
  "FotoKey" varchar(120) NULL,
  "CriadoEm" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_PercursoDemoEventos_PedidoId_CriadoEm"
  ON rentall."PercursoDemoEventos" ("PedidoId", "CriadoEm");

-- Not exposed through the Supabase Data API; keep defence in depth.
REVOKE ALL ON rentall."PercursoDemoEventos" FROM PUBLIC, anon, authenticated;
ALTER TABLE rentall."PercursoDemoEventos" ENABLE ROW LEVEL SECURITY;
-- Append-only for the backend: no UPDATE/DELETE grant.
GRANT SELECT, INSERT ON rentall."PercursoDemoEventos" TO rentall_app;
GRANT USAGE, SELECT ON SEQUENCE rentall."PercursoDemoEventos_Id_seq" TO rentall_app;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'rentall'
      AND tablename = 'PercursoDemoEventos' AND policyname = 'PercursoDemoEventos_backend_only') THEN
    CREATE POLICY "PercursoDemoEventos_backend_only" ON rentall."PercursoDemoEventos"
      FOR ALL TO rentall_app USING (true) WITH CHECK (true);
  END IF;
END $$;

-- Rollback (only if needed; deletes the trail, never other data):
--   DROP TABLE IF EXISTS rentall."PercursoDemoEventos";
